import type { CourseSentence, SentenceLesson } from './courseContent';

/** Additive enrichment for the existing Foundation and Survival lessons.
 * Original sentence wording, IDs, translations, and lesson order stay intact.
 */
export interface FoundationSurvivalLessonExtension {
  durationMinutes: number;
  /** Patterns keep sentence text intact; additive sentences carry their own patterns. */
  patterns: Record<string, string>;
  sentences: CourseSentence[];
  dialogue: SentenceLesson['dialogue'];
}

